import React, { useState, useEffect } from 'react';
import { Link } from 'react-router-dom';
import { 
  TrendingUp, 
  Clock, 
  CheckCircle, 
  XCircle, 
  PlayCircle,
  AlertTriangle,
  GitBranch,
  Activity
} from 'lucide-react';
import { useSocket } from '../context/SocketContext';
import { useAlerts } from '../context/AlertContext';
import axios from 'axios';
import toast from 'react-hot-toast';

const Dashboard = () => {
  const { socket, isConnected } = useSocket();
  const { alerts } = useAlerts();
  const [metrics, setMetrics] = useState(null);
  const [recentPipelines, setRecentPipelines] = useState([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    fetchDashboardData();

    // Set up real-time updates
    if (socket) {
      socket.on('metrics-changed', (data) => {
        setMetrics(data);
      });

      socket.on('pipeline-status-changed', () => {
        fetchDashboardData();
      });
    }

    return () => {
      if (socket) {
        socket.off('metrics-changed');
        socket.off('pipeline-status-changed');
      }
    };
  }, [socket]);

  const fetchDashboardData = async () => {
    try {
      setLoading(true);
      const [metricsRes, pipelinesRes] = await Promise.all([
        axios.get('/api/metrics/dashboard-summary'),
        axios.get('/api/pipelines?limit=10')
      ]);

      setMetrics(metricsRes.data);
      setRecentPipelines(pipelinesRes.data.pipelines || []);
    } catch (error) {
      console.error('Error fetching dashboard data:', error);
      toast.error('Failed to load dashboard data');
    } finally {
      setLoading(false);
    }
  };

  const getStatusIcon = (status) => {
    switch (status) {
      case 'success':
        return <CheckCircle className="h-5 w-5 text-success-500" />;
      case 'failed':
        return <XCircle className="h-5 w-5 text-danger-500" />;
      case 'running':
        return <PlayCircle className="h-5 w-5 text-primary-500 animate-pulse" />;
      case 'pending':
        return <Clock className="h-5 w-5 text-warning-500" />;
      default:
        return <Activity className="h-5 w-5 text-gray-500" />;
    }
  };

  const getStatusColor = (status) => {
    switch (status) {
      case 'success':
        return 'status-success';
      case 'failed':
        return 'status-failed';
      case 'running':
        return 'status-running';
      case 'pending':
        return 'status-pending';
      default:
        return 'status-pending';
    }
  };

  const formatDuration = (seconds) => {
    if (!seconds) return 'N/A';
    const minutes = Math.floor(seconds / 60);
    const remainingSeconds = seconds % 60;
    return `${minutes}m ${remainingSeconds}s`;
  };

  const formatTime = (timestamp) => {
    return new Date(timestamp).toLocaleTimeString();
  };

  if (loading) {
    return (
      <div className="flex items-center justify-center h-64">
        <div className="loading-spinner"></div>
      </div>
    );
  }

  return (
    <div className="space-y-6">
      {/* Page header */}
      <div className="flex items-center justify-between">
        <div>
          <h1 className="text-2xl font-bold text-gray-900">Dashboard</h1>
          <p className="text-gray-600">Real-time CI/CD pipeline monitoring</p>
        </div>
        <div className="flex items-center space-x-2">
          <div className={`h-2 w-2 rounded-full ${isConnected ? 'bg-success-400' : 'bg-danger-400'}`} />
          <span className="text-sm text-gray-600">
            {isConnected ? 'Live' : 'Offline'}
          </span>
        </div>
      </div>

      {/* Key metrics */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
        {/* Success Rate */}
        <div className="metric-card">
          <div className="flex items-center">
            <div className="flex-shrink-0">
              <div className="w-8 h-8 bg-success-100 rounded-lg flex items-center justify-center">
                <TrendingUp className="h-5 w-5 text-success-600" />
              </div>
            </div>
            <div className="ml-4">
              <p className="metric-label">Success Rate</p>
              <p className="metric-value">
                {metrics?.success_rate?.success_rate || 0}%
              </p>
            </div>
          </div>
          <div className="mt-4">
            <div className="flex items-center justify-between text-sm">
              <span className="text-gray-500">Last 24h</span>
              <span className="text-success-600 font-medium">
                {metrics?.success_rate?.successful || 0} / {metrics?.success_rate?.total_pipelines || 0}
              </span>
            </div>
          </div>
        </div>

        {/* Average Build Time */}
        <div className="metric-card">
          <div className="flex items-center">
            <div className="flex-shrink-0">
              <div className="w-8 h-8 bg-primary-100 rounded-lg flex items-center justify-center">
                <Clock className="h-5 w-5 text-primary-600" />
              </div>
            </div>
            <div className="ml-4">
              <p className="metric-label">Avg Build Time</p>
              <p className="metric-value">
                {formatDuration(metrics?.build_time?.avg_build_time)}
              </p>
            </div>
          </div>
          <div className="mt-4">
            <div className="flex items-center justify-between text-sm">
              <span className="text-gray-500">Range</span>
              <span className="text-gray-600 font-medium">
                {formatDuration(metrics?.build_time?.min_build_time)} - {formatDuration(metrics?.build_time?.max_build_time)}
              </span>
            </div>
          </div>
        </div>

        {/* Total Pipelines */}
        <div className="metric-card">
          <div className="flex items-center">
            <div className="flex-shrink-0">
              <div className="w-8 h-8 bg-blue-100 rounded-lg flex items-center justify-center">
                <GitBranch className="h-5 w-5 text-blue-600" />
              </div>
            </div>
            <div className="ml-4">
              <p className="metric-label">Total Pipelines</p>
              <p className="metric-value">
                {metrics?.success_rate?.total_pipelines || 0}
              </p>
            </div>
          </div>
          <div className="mt-4">
            <div className="flex items-center justify-between text-sm">
              <span className="text-gray-500">Running</span>
              <span className="text-primary-600 font-medium">
                {metrics?.success_rate?.running || 0}
              </span>
            </div>
          </div>
        </div>

        {/* Pending Alerts */}
        <div className="metric-card">
          <div className="flex items-center">
            <div className="flex-shrink-0">
              <div className="w-8 h-8 bg-warning-100 rounded-lg flex items-center justify-center">
                <AlertTriangle className="h-5 w-5 text-warning-600" />
              </div>
            </div>
            <div className="ml-4">
              <p className="metric-label">Pending Alerts</p>
              <p className="metric-value">
                {metrics?.pending_alerts || 0}
              </p>
            </div>
          </div>
          <div className="mt-4">
            <div className="flex items-center justify-between text-sm">
              <span className="text-gray-500">Last 24h</span>
              <span className="text-warning-600 font-medium">
                {alerts.length} total
              </span>
            </div>
          </div>
        </div>
      </div>

      {/* Recent Pipelines */}
      <div className="card">
        <div className="card-header">
          <h3 className="text-lg font-medium text-gray-900">Recent Pipelines</h3>
          <Link to="/pipelines" className="text-sm text-primary-600 hover:text-primary-500">
            View all →
          </Link>
        </div>
        <div className="card-body">
          <div className="space-y-4">
            {recentPipelines.map((pipeline) => (
              <div key={pipeline.id} className="flex items-center justify-between p-3 bg-gray-50 rounded-lg">
                <div className="flex items-center space-x-3">
                  {getStatusIcon(pipeline.status)}
                  <div>
                    <p className="text-sm font-medium text-gray-900">{pipeline.name}</p>
                    <p className="text-xs text-gray-500">
                      {formatTime(pipeline.created_at)} • {pipeline.trigger_type}
                    </p>
                  </div>
                </div>
                <div className="flex items-center space-x-2">
                  <span className={getStatusColor(pipeline.status)}>
                    {pipeline.status}
                  </span>
                  {pipeline.build_time && (
                    <span className="text-xs text-gray-500">
                      {formatDuration(pipeline.build_time)}
                    </span>
                  )}
                </div>
              </div>
            ))}
          </div>
        </div>
      </div>
    </div>
  );
};

export default Dashboard;
